Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
net/mlx5e: fix a double-free in arfs_create_groups

When `in` allocated by kvzalloc fails, arfs_create_groups will free
ft->g and return an error. However, arfs_create_table, the only caller of
arfs_create_groups, will hold this error and call to
mlx5e_destroy_flow_table, in which the ft->g will be freed again.

Fixes: 1cabe6b0965e ("net/mlx5e: Create aRFS flow tables")
Signed-off-by: Zhipeng Lu <alexious@zju.edu.cn>
Reviewed-by: Simon Horman <horms@kernel.org>
Signed-off-by: Saeed Mahameed <saeedm@nvidia.com>

Here is the root cause:
The bug is caused by a double-free scenario where the `ft->g` pointer is freed in two different places if the allocation of `in` fails after `ft->g` has already been allocated. This occurs because the error handling logic did not properly account for the order of resource allocation and cleanup, leading to a situation where the same memory is freed multiple times.

Here is the patch:
 				 MLX5E_ARFS_GROUP2_SIZE)
 static int arfs_create_groups(struct mlx5e_flow_table *ft,
 			      enum  arfs_type type)
 {
 	int inlen = MLX5_ST_SZ_BYTES(create_flow_group_in);
 	void *outer_headers_c;
 	int ix = 0;
 	u32 *in;
 	int err;
 	u8 *mc;

 	ft->g = kcalloc(MLX5E_ARFS_NUM_GROUPS,
 			sizeof(*ft->g), GFP_KERNEL);
-	in = kvzalloc(inlen, GFP_KERNEL);
-	if  (!in || !ft->g) {
-		kfree(ft->g);
-		kvfree(in);
+	if (!ft->g)
 		return -ENOMEM;
+
+	in = kvzalloc(inlen, GFP_KERNEL);
+	if (!in) {
+		err = -ENOMEM;
+		goto err_free_g;
 	}

 	mc = MLX5_ADDR_OF(create_flow_group_in, in, match_criteria);
 	outer_headers_c = MLX5_ADDR_OF(fte_match_param, mc,
 				       outer_headers);
 	MLX5_SET_TO_ONES(fte_match_set_lyr_2_4, outer_headers_c, ethertype);
 	switch (type) {
 	case ARFS_IPV4_TCP:
 	case ARFS_IPV6_TCP:
 		MLX5_SET_TO_ONES(fte_match_set_lyr_2_4, outer_headers_c, tcp_dport);
 		MLX5_SET_TO_ONES(fte_match_set_lyr_2_4, outer_headers_c, tcp_sport);
 		break;
 	case ARFS_IPV4_UDP:
 	case ARFS_IPV6_UDP:
 		MLX5_SET_TO_ONES(fte_match_set_lyr_2_4, outer_headers_c, udp_dport);
 		MLX5_SET_TO_ONES(fte_match_set_lyr_2_4, outer_headers_c, udp_sport);
 		break;
 	default:
 		err = -EINVAL;
-		goto out;
+		goto err_free_in;
 	}

 	switch (type) {
 	case ARFS_IPV4_TCP:
 	case ARFS_IPV4_UDP:
 		MLX5_SET_TO_ONES(fte_match_set_lyr_2_4, outer_headers_c,
 				 src_ipv4_src_ipv6.ipv4_layout.ipv4);
 		MLX5_SET_TO_ONES(fte_match_set_lyr_2_4, outer_headers_c,
 				 dst_ipv4_dst_ipv6.ipv4_layout.ipv4);
 		break;
 	case ARFS_IPV6_TCP:
 	case ARFS_IPV6_UDP:
 		memset(MLX5_ADDR_OF(fte_match_set_lyr_2_4, outer_headers_c,
 				    src_ipv4_src_ipv6.ipv6_layout.ipv6),
 		       0xff, 16);
 		memset(MLX5_ADDR_OF(fte_match_set_lyr_2_4, outer_headers_c,
 				    dst_ipv4_dst_ipv6.ipv6_layout.ipv6),
 		       0xff, 16);
 		break;
 	default:
 		err = -EINVAL;
-		goto out;
+		goto err_free_in;
 	}

 	MLX5_SET_CFG(in, match_criteria_enable, MLX5_MATCH_OUTER_HEADERS);
 	MLX5_SET_CFG(in, start_flow_index, ix);
 	ix += MLX5E_ARFS_GROUP1_SIZE;
 	MLX5_SET_CFG(in, end_flow_index, ix - 1);
 	ft->g[ft->num_groups] = mlx5_create_flow_group(ft->t, in);
 	if (IS_ERR(ft->g[ft->num_groups]))
-		goto err;
+		goto err_clean_group;
 	ft->num_groups++;

 	memset(in, 0, inlen);
 	MLX5_SET_CFG(in, start_flow_index, ix);
 	ix += MLX5E_ARFS_GROUP2_SIZE;
 	MLX5_SET_CFG(in, end_flow_index, ix - 1);
 	ft->g[ft->num_groups] = mlx5_create_flow_group(ft->t, in);
 	if (IS_ERR(ft->g[ft->num_groups]))
-		goto err;
+		goto err_clean_group;
 	ft->num_groups++;

 	kvfree(in);
 	return 0;

-err:
+err_clean_group:
 	err = PTR_ERR(ft->g[ft->num_groups]);
 	ft->g[ft->num_groups] = NULL;
-out:
+err_free_in:
 	kvfree(in);
-
+err_free_g:
+	kfree(ft->g);
+	ft->g = NULL;
 	return err;
 }



